#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Amazon SES, Google Calendar, database, then a live check.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="${ENV_FILE:-$ROOT/deploy/.env}"
mkdir -p "$(dirname "$ENV_FILE")"

TOTAL_STAGES=13

banner "Austial booking API: email, calendar and database"

# ── 1. Basics ─────────────────────────────────────────────────────────────
stage "Basics"
say "Everything lands in $ENV_FILE (git-ignored, mode 600)."
say "That file is what you later copy to the server as /opt/api/.env."
echo
ask MAIL_ADDRESS "Sender address, e.g. hello@austial.com:"
while [[ "$MAIL_ADDRESS" != *@*.* ]]; do
  warn "That doesn't look like an email address."
  ask MAIL_ADDRESS "Sender address, e.g. hello@austial.com:"
done
MAIL_DOMAIN="${MAIL_ADDRESS#*@}"
ask MAIL_NOTIFY_TO "Where should new bookings and leads be emailed to (your inbox)?"
ask AWS_REGION "AWS region for SES (ap-south-1 is Mumbai):"
AWS_REGION="${AWS_REGION:-ap-south-1}"
write_env MAIL_FROM "Austial <$MAIL_ADDRESS>"
write_env MAIL_NOTIFY_TO "$MAIL_NOTIFY_TO"
write_env AWS_REGION "$AWS_REGION"
write_env APP_ENV prod
write_env MAIL_BACKEND ses
write_env CALENDAR_BACKEND google
write_env SITE_URL "https://services.austial.com"
write_env CORS_ORIGINS "https://services.austial.com"
write_env TRUSTED_PROXY_HOPS 1
write_env BOOKING_IMAGE "ghcr.io/austial/api-booking:latest"
if [[ -z "$(_existing CODE_PEPPER || true)" ]]; then
  write_env CODE_PEPPER "$(openssl rand -hex 32)"
else
  note "CODE_PEPPER already set, keeping it (changing it breaks open codes and manage links)."
fi
pause

# ── 2. SES: verify the domain ─────────────────────────────────────────────
stage "Amazon SES: verify $MAIL_DOMAIN"
say "SES only sends from identities you have proven you own."
open_url "https://${AWS_REGION}.console.aws.amazon.com/ses/home?region=${AWS_REGION}#/identities"
step "Check the region (top right) is $AWS_REGION. Sign in or create the AWS account if asked."
step "Click Create identity → Identity type: Domain → Domain: $MAIL_DOMAIN."
step "Leave 'Easy DKIM' on (RSA_2048_BIT). Click Create identity."
step "The identity page now lists 3 CNAME records under 'DomainKeys Identified Mail (DKIM)'."
pause "Press Enter once you can see the 3 CNAME records..."

# ── 3. SES: DNS ───────────────────────────────────────────────────────────
stage "Amazon SES: add the DNS records"
say "Add the 3 DKIM CNAME records wherever $MAIL_DOMAIN's DNS is managed."
step "Name = the part before .$MAIL_DOMAIN (some registrars want the full name); Value = the amazonses.com target."
step "Optional but recommended, one TXT record: name _dmarc, value  v=DMARC1; p=none; rua=mailto:$MAIL_NOTIFY_TO"
step "Back in SES, refresh the identity page. Wait for 'Verified' (usually minutes, up to 72 hours)."
note "You can carry on before it turns green; the live check at the end needs it."
pause "Press Enter when you've added the records..."

# ── 4. SES: production access ─────────────────────────────────────────────
stage "Amazon SES: leave the sandbox"
say "New accounts can only email addresses you've verified, so real visitors would get nothing."
open_url "https://${AWS_REGION}.console.aws.amazon.com/ses/home?region=${AWS_REGION}#/account"
step "Click 'Request production access'."
step "Mail type: Transactional. Website URL: https://services.austial.com"
step "Use case description, paste this:"
cat <<'TEXT'

    The Austial services site (services.austial.com) sends transactional email
    only: a 6-digit verification code when a visitor books a discovery call,
    the booking confirmation with a calendar invite, a reminder 24 hours
    before the call, and reschedule or cancellation confirmations. Volume is
    low, under 50 emails a day. Every recipient typed their own address into
    our booking form and asked for the email. We send no marketing email and
    do not buy or scrape addresses. We review bounce and complaint rates in
    the SES console.

TEXT
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy <<'TEXT'
The Austial services site (services.austial.com) sends transactional email only: a 6-digit verification code when a visitor books a discovery call, the booking confirmation with a calendar invite, a reminder 24 hours before the call, and reschedule or cancellation confirmations. Volume is low, under 50 emails a day. Every recipient typed their own address into our booking form and asked for the email. We send no marketing email and do not buy or scrape addresses. We review bounce and complaint rates in the SES console.
TEXT
  note "(copied to your clipboard)"
fi
step "Accept the terms and submit. AWS usually answers within 24 hours; nothing below waits on it."
step "Meanwhile, so the live check can email you from the sandbox: Identities → Create identity → Email address → $MAIL_NOTIFY_TO, then click the link AWS emails you."
pause "Press Enter once the request is submitted..."

# ── 5. SES: IAM user and access key ───────────────────────────────────────
stage "Amazon SES: a send-only IAM user"
say "The API gets its own AWS user that can do nothing except send email."
open_url "https://console.aws.amazon.com/iam/home#/users/create"
step "User name: austial-booking-api. Do not tick console access. Next → Create user (no permissions yet)."
step "Open the new user → Add permissions → Create inline policy → JSON tab, and paste:"
POLICY='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["ses:SendEmail","ses:SendRawEmail"],"Resource":"*"}]}'
printf '\n    %s\n\n' "$POLICY"
if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$POLICY" | pbcopy; note "(copied to your clipboard)"; fi
step "Name it ses-send-only and create it."
step "Security credentials tab → Create access key → 'Application running outside AWS' → Next → Create access key."
ask AWS_ACCESS_KEY_ID "Paste the Access key ID:"
ask_secret AWS_SECRET_ACCESS_KEY "Paste the Secret access key (hidden):"
write_env AWS_ACCESS_KEY_ID "$AWS_ACCESS_KEY_ID"
write_env AWS_SECRET_ACCESS_KEY "$AWS_SECRET_ACCESS_KEY"

# ── 6. Google: project and Calendar API ───────────────────────────────────
stage "Google: project and Calendar API"
say "Sign in with the Google account whose calendar should hold the calls."
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: Austial Booking. Click Create, then make sure it is the selected project (top bar)."
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
step "Click Enable on 'Google Calendar API'."
pause "Press Enter once the API shows as enabled..."

# ── 7. Google: consent screen ─────────────────────────────────────────────
stage "Google: consent screen"
say "Google's page layout changes now and then; the names below stay the same."
open_url "https://console.cloud.google.com/auth/overview"
step "Click Get started. App name: Austial Booking. User support email: yours. Next."
step "Audience: External. Next. Contact email: yours. Agree to the policy, Continue, Create."
step "Left menu → Data Access → Add or remove scopes → tick these two Calendar API scopes → Update → Save:"
note "    .../auth/calendar.events"
note "    .../auth/calendar.freebusy"
step "Left menu → Audience → Publish app → Confirm. Status must read 'In production'."
warn "Do not leave it in 'Testing': Google expires refresh tokens after 7 days and bookings would silently stop."
pause "Press Enter once it says In production..."

# ── 8. Google: OAuth client ───────────────────────────────────────────────
stage "Google: OAuth client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Desktop app. Name: Austial Booking API. Click Create."
step "Copy the Client ID, then copy the Client secret."
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

# ── 9. Google: authorise and capture the refresh token ────────────────────
stage "Google: authorise the API"
if [[ -n "$(_existing GOOGLE_REFRESH_TOKEN || true)" ]] \
   && ! confirm "A refresh token is already saved. Authorise again and replace it?"; then
  note "Keeping the saved refresh token."
else
  say "This opens Google's consent page and catches the redirect on a local port."
  step "Pick the account that owns the calendar."
  step "You will see 'Google hasn't verified this app'. Click Advanced → Go to Austial Booking (unsafe). That is expected: it is your own app."
  step "Tick both calendar permissions and continue."
  pause "Press Enter to open the consent page..."
  if GOOGLE_REFRESH_TOKEN="$(cd "$ROOT" && GOOGLE_CLIENT_ID="$GOOGLE_CLIENT_ID" \
        GOOGLE_CLIENT_SECRET="$GOOGLE_CLIENT_SECRET" uv run python scripts/google_refresh_token.py)" \
     && [[ -n "$GOOGLE_REFRESH_TOKEN" ]]; then
    write_env GOOGLE_REFRESH_TOKEN "$GOOGLE_REFRESH_TOKEN"
  else
    warn "No refresh token captured. Re-run the wizard to try again."
    SKIPPED+=("GOOGLE_REFRESH_TOKEN (re-run scripts/setup-services.sh)")
  fi
fi
echo
say "Which calendar holds the calls? 'primary' is the account's main calendar."
note "For another one: Google Calendar → its Settings → Integrate calendar → Calendar ID."
ask GOOGLE_CALENDAR_ID "Calendar ID (Enter for primary):"
write_env GOOGLE_CALENDAR_ID "${GOOGLE_CALENDAR_ID:-primary}"
pause

# ── 10. Database ──────────────────────────────────────────────────────────
stage "Database: DigitalOcean Managed Postgres"
if confirm "Do you already have the Postgres cluster?"; then
  open_url "https://cloud.digitalocean.com/databases"
  step "Open the cluster → Overview → Connection details."
  step "Pick the 'Public network' (or 'VPC network' if the Droplet is in the same region) and the 'Connection string' view."
  step "Copy the whole string; it starts with postgresql://"
  ask_secret DATABASE_URL "Paste the connection string (hidden):"
  case "$DATABASE_URL" in
    postgresql+asyncpg://*) ;;
    postgresql://*) DATABASE_URL="postgresql+asyncpg://${DATABASE_URL#postgresql://}" ;;
    postgres://*)   DATABASE_URL="postgresql+asyncpg://${DATABASE_URL#postgres://}" ;;
    *) warn "That doesn't look like a Postgres URL; saving it anyway." ;;
  esac
  DATABASE_URL="${DATABASE_URL//sslmode=/ssl=}"
  write_env DATABASE_URL "$DATABASE_URL"
  note "Converted for the async driver (postgresql+asyncpg, ssl=require)."
else
  SKIPPED+=("DATABASE_URL (create the cluster, then re-run this wizard)")
  warn "Skipped. Create the cluster first (Create → Databases → PostgreSQL), then re-run."
fi
pause

# ── 11. Live check: email ─────────────────────────────────────────────────
stage "Check: Amazon SES"
if confirm "Send a real test email to $MAIL_NOTIFY_TO now?"; then
  (cd "$ROOT" && uv run python scripts/check_setup.py "$ENV_FILE" --only ses) \
    || warn "SES check failed. Usual causes: DKIM not verified yet, still in the sandbox, or $MAIL_NOTIFY_TO not verified."
else
  note "Skipped. Later: uv run python scripts/check_setup.py"
fi
pause

# ── 12. Live check: calendar ──────────────────────────────────────────────
stage "Check: Google Calendar"
if confirm "Read free/busy from Google now?"; then
  (cd "$ROOT" && uv run python scripts/check_setup.py "$ENV_FILE" --only google) \
    || warn "Google check failed. Re-run the wizard and redo the authorise stage."
  if confirm "Also create and delete a throwaway event (proves Google Meet links work; emails you an invite)?"; then
    (cd "$ROOT" && uv run python scripts/check_setup.py "$ENV_FILE" --only google --event) \
      || warn "Event check failed. Is the Calendar API enabled and the app In production?"
  fi
else
  note "Skipped. Later: uv run python scripts/check_setup.py --event"
fi
pause

# ── 13. Put it on the server ──────────────────────────────────────────────
stage "Hand the env file to the server"
say "Your finished file is $ENV_FILE."
say "On the Droplet it must live at /opt/api/.env (mode 600). From this machine:"
printf '\n    scp "%s" root@YOUR_DROPLET_IP:/opt/api/.env\n\n' "$ENV_FILE"
note "That needs the Droplet to exist (see deploy/ and the README). Never commit this file."
pause

finish
}

run_wizard "$@"; exit
